update meal_order
residentId = #{userid,jdbcType=INTEGER}, dishId = #{dishId,jdbcType=INTEGER}, orderTime = #{MealOrdertime,jdbcType=TIMESTAMP}, completeTime = #{returntime,jdbcType=TIMESTAMP}, quantity = #{quantity,jdbcType=INTEGER}, unitPrice = #{unitPrice,jdbcType=DECIMAL}, totalPrice = #{totalPrice,jdbcType=DECIMAL}, orderStatus = #{orderStatus,jdbcType=VARCHAR}, mealDate = #{mealDate,jdbcType=DATE}, mealSlot = #{mealSlot,jdbcType=VARCHAR}, deliveryType = #{deliveryType,jdbcType=VARCHAR}, pickupCode = #{pickupCode,jdbcType=VARCHAR}, contactPhone = #{contactPhone,jdbcType=VARCHAR}, deliveryAddress = #{deliveryAddress,jdbcType=VARCHAR}, remark = #{remark,jdbcType=VARCHAR}, payStatus = #{payStatus,jdbcType=VARCHAR}, paidAt = #{paidAt,jdbcType=TIMESTAMP}, cancelReason = #{cancelReason,jdbcType=VARCHAR},
where orderId = #{MealOrderid,jdbcType=INTEGER}

update meal_order
set residentId = #{userid,jdbcType=INTEGER},
  dishId = #{dishId,jdbcType=INTEGER},
  orderTime = #{MealOrdertime,jdbcType=TIMESTAMP},
  completeTime = #{returntime,jdbcType=TIMESTAMP}
where orderId = #{MealOrderid,jdbcType=INTEGER}

mapper.select:
select count(*) from meal_order, resident, dish_info where meal_order.residentId = resident.residentId and meal_order.dishId = dish_info.dishId
and residentName like concat('%',#{username},'%')
and dishName like concat('%',#{dishName},'%')
and dishName like concat('%',#{dishName},'%')
and meal_order.residentId = #{userid}
and meal_order.residentId = #{residentId}

select meal_order.orderId, meal_order.residentId, meal_order.dishId, meal_order.orderTime, meal_order.completeTime, meal_order.quantity, meal_order.unitPrice, meal_order.totalPrice, meal_order.orderStatus, meal_order.mealDate, meal_order.mealSlot, meal_order.deliveryType, meal_order.pickupCode, meal_order.contactPhone, meal_order.deliveryAddress, meal_order.remark, meal_order.payStatus, meal_order.paidAt, meal_order.cancelReason, meal_order.createdAt, meal_order.updatedAt, residentName, dishName from meal_order, resident, dish_info where meal_order.residentId = resident.residentId and meal_order.dishId = dish_info.dishId
and residentName like concat('%',#{username},'%')
and dishName like concat('%',#{dishName},'%')
and dishName like concat('%',#{dishName},'%')
and meal_order.residentId = #{userid}
and meal_order.residentId = #{residentId}
order by field(orderStatus, 'PENDING', 'CONFIRMED', 'COMPLETED', 'CANCELLED'), createdAt desc limit #{begin}, #{size}
